  def eventualSafeNodes(graph: Array[Array[Int]]): List[Int] = {
    val n = graph.length
    // States: 0 = unvisited, 1 = visiting, 2 = safe
    val state = Array.fill(n)(0)

    def dfs(u: Int): Boolean = {
      if (state(u) != 0) return state(u) == 2
      state(u) = 1
      for (v <- graph(u)) {
        if (state(v) == 1 || !dfs(v)) return false
